import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color } = ctx.THREE;
  const root = new Group();
  root.name = config?.id ?? 'collection-card-1';

  const resources = [];
  const timelines = [];
  let disposed = false;

  const width = 1.6;
  const height = 1.0;
  const frameDepth = 0.018;
  const frameThickness = 0.025;

  const frameMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.9
  });
  resources.push(frameMaterial);

  const frameParts = [
    {
      geometry: new BoxGeometry(width, frameThickness, frameDepth),
      position: [0, height * 0.5, 0.025]
    },
    {
      geometry: new BoxGeometry(width, frameThickness, frameDepth),
      position: [0, -height * 0.5, 0.025]
    },
    {
      geometry: new BoxGeometry(frameThickness, height, frameDepth),
      position: [-width * 0.5, 0, 0.025]
    },
    {
      geometry: new BoxGeometry(frameThickness, height, frameDepth),
      position: [width * 0.5, 0, 0.025]
    }
  ];

  for (const part of frameParts) {
    const frame = new Mesh(part.geometry, frameMaterial);
    frame.position.set(...part.position);
    root.add(frame);
    resources.push(part.geometry);
  }

  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 1
  });
  const imageGeometry = new PlaneGeometry(
    width - frameThickness * 2,
    height - frameThickness * 2
  );
  const imageMesh = new Mesh(imageGeometry, imageMaterial);
  imageMesh.position.z = 0;
  root.add(imageMesh);
  resources.push(imageGeometry, imageMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const label = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    label.position.set(-width * 0.38, -height * 0.27, 0.06);
    root.add(label);
  }

  const signalMarkerGeometry = new BoxGeometry(0.16, 0.025, 0.025);
  const signalMarker = new Mesh(signalMarkerGeometry, frameMaterial);
  signalMarker.position.set(-width * 0.38, height * 0.27, 0.06);
  root.add(signalMarker);
  resources.push(signalMarkerGeometry);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed || !texture) return;

      const localTexture = texture.clone();
      const image = localTexture.image;
      const atlasWidth = image?.width || 512;
      const atlasHeight = image?.height || 320;
      const source = config.atlasRegion?.sourceRect ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      localTexture.repeat.set(
        source.width / atlasWidth,
        source.height / atlasHeight
      );
      localTexture.offset.set(
        source.x / atlasWidth,
        1 - (source.y + source.height) / atlasHeight
      );
      localTexture.needsUpdate = true;

      if (ctx.THREE.SRGBColorSpace) {
        localTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      imageMaterial.map = localTexture;
      imageMaterial.needsUpdate = true;
      resources.push(localTexture);
    }).catch(() => {});
  }

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) {
      root.quaternion.copy(camera.quaternion);
    }
  };

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry && !resources.includes(object.geometry)) {
        object.geometry.dispose?.();
      }
    });

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
